	private static void assertPatternMatchesReference(TripleIndex index, String scoreSequence, String orderSequence,
			long[] pattern) {
		assertEquals(originalScore(scoreSequence, pattern),
				index.getPatternScore(pattern[0], pattern[1], pattern[2], pattern[3]),
				() -> "Score for " + scoreSequence + " and " + Arrays.toString(pattern));
		for (StatementOrder order : StatementOrder.values()) {
			assertEquals(originalSupportsOrder(orderSequence, order, pattern),
					index.supportsOrder(order, pattern[0], pattern[1], pattern[2], pattern[3]),
					() -> order + " order for " + orderSequence + " and " + Arrays.toString(pattern));
		}
	}

	private static void assertSelectionMatchesReference(List<TripleIndex> indexes) {
		assertSelectionMatchesReference(indexes, new TripleIndex.IndexSelection(indexes));
	}

	private static void assertSelectionMatchesReference(List<TripleIndex> indexes,
			TripleIndex.IndexSelection selection) {
		for (int mask = 0; mask < 16; mask++) {
			long[] pattern = mixedPattern(mask);
			for (StatementOrder order : StatementOrder.values()) {
				TripleIndex expected = originalBestOrderedIndex(indexes, order, pattern);
				String message = "Indexes " + indexes + ", mask " + mask + ", order " + order;
				assertSame(expected, selection.getBestCompatibleOrderedIndex(order, pattern[0], pattern[1],
						pattern[2], pattern[3]), message);
				assertSame(expected, selection.getBestCompatibleOrderedIndex(order, mask), message);
				assertSame(expected, TripleIndex.getBestCompatibleOrderedIndex(indexes, order, pattern[0], pattern[1],
						pattern[2], pattern[3]), message);
			}
		}
	}

	/** A scan of the original prefix rules; deliberately does not call any precomputed methods. */
	private static TripleIndex originalBestOrderedIndex(List<TripleIndex> indexes, StatementOrder order,
			long[] pattern) {
		int bestScore = -1;
		TripleIndex best = null;
		for (TripleIndex index : indexes) {
			String sequence = new String(index.getFieldSeq());
			if (originalSupportsOrder(sequence, order, pattern)) {
				int score = originalScore(sequence, pattern);
				if (score > bestScore) {
					best = index;
					bestScore = score;
				}
			}
		}
		return best;
	}

	private static int originalPrefixComponentMask(String sequence, int boundMask) {
		int prefix = 0;
		for (char field : sequence.toCharArray()) {
			int bit = switch (field) {
			case 's' -> 1;
			case 'p' -> 2;
			case 'o' -> 4;
			case 'c' -> 8;
			default -> throw new AssertionError("Unexpected field: " + field);
			};
			if ((boundMask & bit) == 0) {
				break;
			}
			prefix |= bit;
		}
		return prefix;
	}

	private static int originalScore(String sequence, long[] pattern) {
		for (int position = 0; position < sequence.length(); position++) {
			if (value(sequence.charAt(position), pattern) < 0) {
				return position;
			}
		}
		return sequence.length();
	}

	private static boolean originalSupportsOrder(String sequence, StatementOrder order, long[] pattern) {
		char orderedField = switch (order) {
		case S -> 's';
		case P -> 'p';
		case O -> 'o';
		case C -> 'c';
		};
		int orderedPosition = sequence.indexOf(orderedField);
		for (int position = 0; position < orderedPosition; position++) {
			if (value(sequence.charAt(position), pattern) < 0) {
				return false;
			}
		}
		return orderedPosition >= 0;
	}

	private static long value(char field, long[] pattern) {
		return switch (field) {
		case 's' -> pattern[0];
		case 'p' -> pattern[1];
		case 'o' -> pattern[2];
		case 'c' -> pattern[3];
		default -> throw new AssertionError("Unexpected field: " + field);
		};
	}

	private static long[] pattern(int mask, long bound, long unbound) {
		long[] pattern = new long[4];
		for (int component = 0; component < pattern.length; component++) {
			pattern[component] = (mask & (1 << component)) == 0 ? unbound : bound;
		}
		return pattern;
	}

	private static long[] mixedPattern(int mask) {
		long[] bound = { 0, 1, Long.MAX_VALUE, 0 };
		long[] unbound = { Long.MIN_VALUE, -2, -1, Long.MIN_VALUE };
		long[] pattern = new long[4];
		for (int component = 0; component < pattern.length; component++) {
			pattern[component] = (mask & (1 << component)) == 0 ? unbound[component] : bound[component];
		}
		return pattern;
	}

	private static List<TripleIndex> indexes(List<String> fieldSequences) throws IOException {
		List<TripleIndex> indexes = new ArrayList<>();
		for (String fieldSequence : fieldSequences) {
			indexes.add(index(fieldSequence));
		}
		return indexes;
	}

	private static TripleIndex index(String fieldSequence) throws IOException {
		// No database is opened: these tests exercise Java-only metadata and must not close the dummy handle.
		return new TripleIndex(fieldSequence, fieldSequence, false, 0, 0, (txn, name, flags) -> 1);
	}

	private static List<String> permutations(String remaining) {
		if (remaining.isEmpty()) {
			return List.of("");
		}
		List<String> permutations = new ArrayList<>();
		for (int i = 0; i < remaining.length(); i++) {
			String suffix = remaining.substring(0, i) + remaining.substring(i + 1);
			for (String permutation : permutations(suffix)) {
				permutations.add(remaining.charAt(i) + permutation);
			}
		}
		return permutations;
	}

	private static final class ProbeGuardIndex extends TripleIndex {
		boolean rejectProbes;

		ProbeGuardIndex(String fieldSequence) throws IOException {
			super(fieldSequence, fieldSequence, false, 0, 0, (txn, name, flags) -> 1);
		}

		@Override
		public int getPatternScore(long subj, long pred, long obj, long context) {
			if (rejectProbes) {
				throw new AssertionError("Selection must use the precomputed winner without scoring indexes");
			}
			return super.getPatternScore(subj, pred, obj, context);
		}

		@Override
		boolean supportsOrder(StatementOrder order, long subj, long pred, long obj, long context) {
			if (rejectProbes) {
				throw new AssertionError("Selection must use the precomputed winner without checking index order");
			}
			return super.supportsOrder(order, subj, pred, obj, context);
		}
	}
